  courseEdit: { open: "என் பாடநெறியைத் திருத்து", done: "திருத்தம் முடிந்தது", title: "உங்கள் பாடநெறியை வடிவமையுங்கள்", undo: "செயல்தவிர்", redo: "மீண்டும் செய்", ask: "ஒரு பகுதி சேர்", askPh: "எ.கா. வேலை விண்ணப்பங்களுக்கு AI பயன்படுத்துவது பற்றி ஒரு பகுதி", add: "AI உடன் சேர்", added: "புதிய பகுதி சேர்க்கப்பட்டது — திறக்கும்போது பாடங்கள் எழுதப்படும்.", hideHint: "குறிப்பு: தேவையில்லாத பகுதிகள்/பாடங்களைக் கண் பொத்தானால் மறையுங்கள். எதுவும் நீக்கப்படாது.", hide: "மறை", hideItem: "“{{title}}” மறை", hidden: "மறைக்கப்பட்டவை (மீண்டும் காட்டத் தொடுங்கள்)", sources: "மூலங்கள்", sourcesHint: "இணைக்கும் ஆவணங்களைப் புதிய பாடங்கள் பயன்படுத்தும்.", remove: "நீக்கு", budget: "இன்றைக்குப் போதுமான திருத்தங்கள்.", nothing: "அங்கே மாற்ற ஒன்றுமில்லை." },
  careerPlus: { title: "என் தொழில் இலக்கு", cvSub: "உங்களிடம் ஏற்கனவே உள்ள திறன்களைப் பார்க்க CV பதிவேற்றுங்கள்.", upload: "CV பதிவேற்று (PDF, Word அல்லது உரை)", privacy: "உங்கள் பணி, திறன்களை அறிய ஒருமுறை மட்டும் படிக்கிறோம் — கோப்பு சேமிக்கப்படாது, தனிப்பட்ட விவரங்கள் புறக்கணிக்கப்படும்.", years_one: "{{count}} ஆண்டு", years_other: "{{count}} ஆண்டு", role: "விரும்பும் பணி", rolePh: "நான் ஆக விரும்புவது… எ.கா. தரவு பகுப்பாய்வாளர்", plan: "என் பாதையைக் காட்டு", needs: "இந்தப் பணிக்குத் தேவை:", missing: "கற்க வேண்டியவை:", followed: "இப்போது பின்தொடர்வது: {{names}}", start: "இந்தப் பாடநெறியைத் தொடங்கு", limit: "இன்றைய வரம்பு முடிந்தது — நாளை முயலுங்கள்.", badFile: "5 MB-க்குள் PDF, Word (.docx) அல்லது உரைக் கோப்பைப் பதிவேற்றுங்கள்." },
  workRole: { title: "எங்கே பணிபுரிகிறீர்கள் / படிக்கிறீர்கள்?", sub: "விருப்பம் — உங்கள் உலகிலிருந்து எடுத்துக்காட்டுகளைப் பயன்படுத்தக் {{mascot}}-க்கு உதவும்.", org: "நிறுவனம்", orgPh: "நிறுவனம், கல்லூரி அல்லது பள்ளிப் பெயர்", lookUp: "தேடு", role: "உங்கள் பணி", rolePh: "உங்கள் பணி, எ.கா. விற்பனை நிர்வாகி", explain: "இதில் என்ன அடங்கும்", keySkills: "முக்கியத் திறன்கள்", optional: "இந்தப் படியைத் தவிர்க்கலாம்." },
