  extension: { title: "உலாவி துணை", sub: "உலாவிப் பணிகளை உண்மையான இணையதளத்திலேயே செய்து, Aasan Companion நீட்டிப்பிலிருந்து நேரடியாகச் சான்றை அனுப்புங்கள் — திரைப்பிடிப்பைச் சேமிக்கவோ பதிவேற்றவோ தேவையில்லை.", connect: "நீட்டிப்பை இணைக்கவும்", codeLabel: "இந்தக் குறியீட்டை நீட்டிப்பில் உள்ளிடுங்கள்", expires: "{{time}} இல் காலாவதியாகும்", expired: "இந்தக் குறியீடு காலாவதியாகிவிட்டது. புதியதைப் பெறுங்கள்.", newCode: "புதிய குறியீடு பெறுக", none: "இன்னும் எந்த உலாவியும் இணைக்கப்படவில்லை.", connected: "{{date}} அன்று இணைக்கப்பட்டது", used: "கடைசியாகப் பயன்படுத்தியது {{date}}", remove: "நீக்கு", removed: "உலாவி துண்டிக்கப்பட்டது.", steps: "Chrome அல்லது Edge இல் Aasan Companion-ஐ நிறுவி, அதைத் திறந்து, கீழே உள்ள குறியீட்டை உள்ளிடுங்கள். உங்கள் கடவுச்சொல்லை நீட்டிப்பில் ஒருபோதும் உள்ளிட வேண்டியதில்லை.", hint: "Aasan Companion நீட்டிப்பைப் பயன்படுத்தி இணையதளத்திலிருந்தே நேரடியாகச் சமர்ப்பிக்கலாம்.", hintLink: "இணைக்கவும்" },
