      tools: {"calculator":{"name":"கால்குலேட்டர்","desc":"சதவீதம், ஜிஎஸ்டி, வட்டி போன்ற கணக்குகளைத் துல்லியமாகப் போடும்."},"workshop_notes":{"name":"பயிலரங்கக் குறிப்புகள்","desc":"இந்தப் பயிலரங்கின் பாடப்பொருளில் சரியான பகுதியைத் தேடித் தரும்."},"datetime":{"name":"தேதியும் நேரமும்","desc":"இன்றைய தேதி, நேரம், நேர மண்டலங்கள், நாட்களை எண்ணுதல்."},"units":{"name":"அலகு மாற்றி","desc":"நீளம், எடை, வெப்பநிலை, கொள்ளளவு, வேகம், பரப்பு, டேட்டா அளவுகளை மாற்றும்."},"word_count":{"name":"சொல் எண்ணிக்கை","desc":"சொற்கள், எழுத்துகள், வாக்கியங்களை எண்ணி, படிக்கும் நேரத்தைக் கணிக்கும்."}},
