      runErr: {"no_runs_left":"இந்தப் பயிலரங்கிற்கான எல்லாச் சோதனைச் செய்திகளையும் பயன்படுத்திவிட்டீர்கள்.","budget":"இந்தப் பயிலரங்கிற்கான இன்றைய AI உதவி தீர்ந்துவிட்டது. உங்கள் முன்னேற்றம் சேமிக்கப்பட்டுள்ளது — நாளை தொடருங்கள்.","rate_limited":"ஒரே நேரத்தில் நிறைய செய்திகள். சிறிது காத்திருந்து மீண்டும் முயலுங்கள்.","too_long":"அந்தச் செய்தி மிக நீளம் — சுருக்கமாக முயலுங்கள்.","empty":"முதலில் ஒரு செய்தியைத் தட்டச்சு செய்யுங்கள்.","not_started":"முதலில் பயிலரங்கைத் தொடங்குங்கள்.","no_pending":"அந்தக் கோரிக்கைக்கு ஏற்கனவே பதில் சொல்லிவிட்டீர்கள்.","bad_call":"அந்தக் கருவிக் கோரிக்கை சரியானதல்ல. மீண்டும் முயலுங்கள்.","session_submitted":"இந்தப் பயிலரங்கு ஏற்கனவே சமர்ப்பிக்கப்பட்டுவிட்டது; இனி ஏஜென்டை மாற்றவோ சோதிக்கவோ முடியாது.","step_limit":"பதில் இல்லாமல் உங்கள் ஏஜென்ட் அதிகப் படிகள் எடுத்துவிட்டது. அதன் அறிவுறுத்தல்களை இன்னும் தெளிவாக்கிப் பாருங்கள்.","tool_failed":"இந்த முறை ஒரு கருவி வேலை செய்யவில்லை. மீண்டும் முயலுங்கள்.","generic":"உங்கள் ஏஜென்டால் இப்போது பதில் சொல்ல முடியவில்லை. மீண்டும் முயலுங்கள்."},
